export const PX={"thromb":{"cat":tr("周邊血管介入 · 急性肢體缺血"),"title":tr("把塞住淺股動脈的血栓清掉"),"text":tr("急性肢體缺血是血管急症：腳突然冰冷、蒼白、沒有脈搏、疼痛、麻木或無力。除了外科取栓與溶栓，也可以經導管直接把血栓清除。下方可切換三種動脈用與一種靜脈用（Aspirex）的機械性血栓清除器械；器械大小為教學示意。"),"steps":{"0":{"rotarex":[tr("急性肢體缺血"),tr("右側淺股動脈被一長段紅褐色血栓塞住（栓塞或原位血栓），遠端沒有血流：腳冰冷、蒼白、脈搏消失，需要盡快打通。已由右側總股動脈順向放好鞘管。")],"angiojet":[tr("急性肢體缺血"),tr("右側淺股動脈被一長段紅褐色血栓塞住（栓塞或原位血栓），遠端沒有血流：腳冰冷、蒼白、脈搏消失，需要盡快打通。已由右側總股動脈順向放好鞘管。")],"indigo":[tr("急性肢體缺血"),tr("右側淺股動脈被一長段紅褐色血栓塞住（栓塞或原位血栓），遠端沒有血流：腳冰冷、蒼白、脈搏消失，需要盡快打通。已由右側總股動脈順向放好鞘管。")],"aspirex":[tr("外髂靜脈血栓"),tr("左側外髂靜脈到總股靜脈有一段紅褐色血栓（髂股靜脈深部靜脈栓塞），腿部腫脹，深部靜脈回流（藍點）受阻。病人俯臥，由左膕靜脈放入鞘管，準備直接把血栓吸掉。")]},"3":{"rotarex":[tr("導絲通過血栓"),tr("導絲輕柔穿過整段血栓，送到膕動脈，之後所有器械都沿著它進出。")],"angiojet":[tr("導絲通過血栓"),tr("導絲輕柔穿過整段血栓，送到膕動脈，之後所有器械都沿著它進出。")],"indigo":[tr("導絲通過血栓"),tr("導絲輕柔穿過整段血栓，送到膕動脈，之後所有器械都沿著它進出。")],"aspirex":[tr("導絲通過血栓"),tr("導絲由膕靜脈沿股靜脈往上，穿過外髂靜脈的血栓，送到下腔靜脈。")]},"7":{"rotarex":[tr("旋轉抽吸（Rotarex）"),tr("沿導絲送入 Rotarex：導管頭內的螺旋高速旋轉，在頭端側窗產生負壓，把血栓吸進窗口、打碎後沿導管抽出體外。慢慢前進、後退、再前進，一段一段清掉。")],"angiojet":[tr("流變式血栓清除（AngioJet）"),tr("沿導絲送入 AngioJet：導管頭端向後噴出高速生理食鹽水（淡藍色），形成負壓把血栓吸進導管、打碎排出；也可先用 Power Pulse 把溶栓藥噴進血栓再抽。動脈與靜脈血栓都可使用。")],"indigo":[tr("連續抽吸（Indigo）"),tr("送入大管徑的 Indigo 抽吸導管，接上幫浦持續抽吸，頂住血栓前端慢慢推進，把血栓整塊吸進導管；分離導絲（separator）前後移動，避免血栓卡住管口。動脈與靜脈血栓都可使用。")],"aspirex":[tr("旋轉抽吸（Aspirex）"),tr("沿導絲送入大管徑的 Aspirex：和 Rotarex 同樣是導管頭內螺旋高速旋轉、側窗負壓抽吸，把血栓吸進去打碎後排出，但管徑較大、專為靜脈設計。在外髂靜脈內來回慢慢推進，一段一段清掉血栓。")]},"20.5":{"rotarex":[tr("血流恢復"),tr("撤出器械後造影，血栓清除、管腔恢復，遠端血流回來；若底下還有狹窄，可再以氣球或支架處理。術後要注意再灌流後的腔室症候群。")],"angiojet":[tr("血流恢復"),tr("撤出器械後造影，血栓清除、管腔恢復，遠端血流回來；若底下還有狹窄，可再以氣球或支架處理。術後要注意再灌流後的腔室症候群。")],"indigo":[tr("血流恢復"),tr("撤出器械後造影，血栓清除、管腔恢復，遠端血流回來；若底下還有狹窄，可再以氣球或支架處理。術後要注意再灌流後的腔室症候群。")],"aspirex":[tr("回流恢復"),tr("撤出器械後造影，外髂靜脈通暢、深部靜脈回流（藍點）恢復；若底下有髂靜脈壓迫或狹窄，可再放靜脈支架。之後持續抗凝治療。")]}}},"lysis":{"cat":tr("周邊血管介入 · 深部靜脈栓塞"),"title":tr("用導管把溶栓藥送進血栓"),"text":tr("大範圍的髂股靜脈血栓，除了抗凝治療，部分病人可做導管溶栓（catheter-directed thrombolysis），以減少日後腿部慢性腫脹、色素沉著、潰瘍等血栓後症候群。下方可切換兩種溶栓導管；器械大小為教學示意。"),"steps":{"0":[tr("髂股靜脈血栓"),tr("左側股靜脈（舊稱「淺股靜脈」，屬於深部靜脈）一路往上到總髂靜脈，有一長段紅褐色血栓（髂股靜脈深部靜脈栓塞）。這是 May-Thurner 症候群的典型例子：右總髂動脈從前方壓住左總髂靜脈，血流淤滯而形成血栓。整條腿腫脹疼痛，深部靜脈回流（藍點）幾乎停止。病人俯臥，由左膕靜脈放入鞘管。")],"3":[tr("導絲通過血栓"),tr("導絲由膕靜脈往上穿過整段血栓，送到下腔靜脈。")],"7":{"ekos":[tr("放置 EKOS 導管"),tr("沿導絲放入超音波輔助溶栓導管（EKOS），兩端標記涵蓋整段血栓。導管內的超音波核心發出低能量超音波（淡藍色波紋），把纖維蛋白鬆開，讓溶栓藥更深入血栓，可用較低藥量完成溶栓。")],"fountain":[tr("放置 Fountain 導管"),tr("沿導絲放入多側孔溶栓導管（Fountain），兩端標記涵蓋整段血栓。可用脈衝噴灑（pulse-spray）從許多側孔把溶栓藥打進血栓（黃色點），再持續滴注。")]},"10":{"ekos":[tr("超音波＋溶栓藥"),tr("低劑量 t-PA 經導管滴注的同時，EKOS 導管內的超音波核心持續發出低能量超音波（淡藍色波紋一圈圈往外震盪）。超音波本身不會打碎血栓，而是讓纖維蛋白鬆開、把藥物推進血栓深處，因此溶得較快、用藥較少。實際約 12–24 小時（這裡壓縮成數秒）；期間要監測出血。")],"fountain":[tr("脈衝噴灑＋滴注"),tr("先用脈衝噴灑（pulse-spray）把 t-PA 從多個側孔一陣陣打進血栓（黃色點），讓藥物直接滲入血栓，再改為持續滴注。沒有超音波，靠藥物本身溶解血栓；實際約 12–24 小時（這裡壓縮成數秒），期間要監測出血。")]},"24":[tr("靜脈支架"),tr("血栓溶解後造影，看到左總髂靜脈被右總髂動脈壓扁的狹窄（May-Thurner）。放置靜脈專用的自膨式鎳鈦合金支架：從外髂靜脈一路撐到總髂靜脈匯入下腔靜脈處，支架徑向支撐力強、足以對抗動脈的壓迫，降低血栓復發。")],"27":[tr("回流恢復"),tr("髂靜脈支架放好後，股靜脈到下腔靜脈全程通暢，深部靜脈回流（藍點）恢復，腿部腫脹逐漸消退；之後持續抗凝治療。")]}},"calc":{"cat":tr("周邊血管介入 · 鈣化動脈"),"title":tr("氣球撐不開時：斑塊切除術"),"text":tr("嚴重鈣化的淺股動脈，氣球常撐不開或造成剝離。斑塊切除術（atherectomy）先把鈣化與斑塊切除，再用氣球撐開、放置支架完成治療。下方可切換兩種斑塊切除器械；器械大小為教學示意。"),"steps":{"0":[tr("嚴重鈣化狹窄"),tr("右側淺股動脈中遠段有一長段嚴重鈣化斑塊（乳白色），管腔只剩細縫，走路小腿痠痛（間歇性跛行）。由右總股動脈順向放入鞘管，導絲已穿過病灶。")],"3":[tr("氣球撐不開"),tr("先用氣球加壓，但鈣化太硬，氣球在病灶中段留下腰身（dog-bone），撐不開；放氣撤出。")],"8":{"jetstream":[tr("旋切斑塊切除（Jetstream）"),tr("改送入 Jetstream：前端是可展開的旋轉切刀，第一趟刀片收合、第二趟刀片張開，高速旋轉切除鈣化與斑塊，碎屑同時由導管抽吸帶出（乳白色碎屑）。")],"hawkone":[tr("定向斑塊切除（HawkOne）"),tr("改送入 HawkOne 定向切除導管：導管靠向一側血管壁，側窗內的切刀高速旋轉，推進時把斑塊削下、收進前端的鼻錐；每趟轉 90 度換一面，共切四個方向。常搭配遠端栓塞保護裝置。")]},"21":[tr("氣球擴張"),tr("斑塊切除後，再用一般氣球撐開：剩下的鈣化斑塊被壓扁、碎裂並推向管壁，這次氣球完全撐開、沒有腰身。")],"29":[tr("血流暢通"),tr("管腔撐開、支架貼壁，遠端血流恢復暢通（紅點）。")],"25.5":[tr("置放支架"),tr("沿導絲送入支架，以氣球撐開讓支架完全貼齊血管壁，再放氣撤出氣球。")]}}},DEVN={"rotarex":"Rotarex","angiojet":"AngioJet","indigo":"Indigo","ekos":"EKOS","fountain":"Fountain","jetstream":"Jetstream","hawkone":"HawkOne","aspirex":tr("Aspirex（靜脈）")};
